sys_script_include.script:
var PlacementDriveUtils = Class.create();
PlacementDriveUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEligibleStudentCount: function() {
        var minCgpa = this.getParameter('sysparm_min_cgpa');
        var branches = this.getParameter('sysparm_branches');

        if (!minCgpa || !branches) {
            return '0';
        }

        var branchList = branches.split(',');

        var studentAgg = new GlideAggregate('x_snc_college_pl_0_student');
        studentAgg.addQuery('cgpa', '>=', minCgpa);
        studentAgg.addQuery('branch', 'IN', branchList);
        studentAgg.addAggregate('COUNT');
        studentAgg.query();

        if (studentAgg.next()) {
            return studentAgg.getAggregate('COUNT') || '0';
        }
        return '0';
    },

    type: 'PlacementDriveUtils'
});
